args.script:
(() => {
  const bodyText = document.body.innerText;
  const audioButtons = [...document.querySelectorAll('span.uk, span.us, .pron-info, .dpron-i, .daud, button')].map(el => ({tag: el.tagName, class: el.className, text: el.innerText || el.getAttribute('aria-label') || el.title || ''}));
  return {bodyText: bodyText.slice(0, 2000), audioButtons};
})()

(() => {
  const entry = document.querySelector('.entry-body__el') || document.body;
  const audios = [...entry.querySelectorAll('span.uk, .uk, span.us, .us, .daud, audio, source, button, .dpron-i')].slice(0,80).map((el, i) => ({
    i,
    tag: el.tagName,
    class: el.className,
    text: (el.innerText || el.textContent || '').trim(),
    aria: el.getAttribute('aria-label'),
    title: el.getAttribute('title'),
    dataSrcMp3: el.getAttribute('data-src-mp3'),
    dataSrcOgg: el.getAttribute('data-src-ogg'),
    id: el.id,
    html: el.outerHTML.slice(0,500)
  }));
  return audios;
})()

(() => {
  const items = [...document.querySelectorAll('.entry-body__el .dpron-i')].map((el, idx) => {
    const btn = el.querySelector('.daud button, button, .daud');
    const audio = el.querySelector('audio');
    const sources = [...el.querySelectorAll('source')].map(s => ({type:s.type, src:s.src || s.getAttribute('src')}));
    return {
      idx,
      class: el.className,
      text: el.innerText.trim(),
      btnText: btn ? btn.innerText.trim() : null,
      btnAria: btn ? btn.getAttribute('aria-label') : null,
      btnTitle: btn ? btn.getAttribute('title') : null,
      btnClass: btn ? btn.className : null,
      audioId: audio ? audio.id : null,
      sources,
      html: el.outerHTML.slice(0,1200)
    };
  });
  return items;
})()
